         if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==c:
          seen.add(q); todo.append(q)
       ys=[p[0] for p in pts]; xs=[p[1] for p in pts]; t,b,l,r=min(ys),max(ys),min(xs),max(xs)
       if b-t>=2 and r-l>=2 and len(pts)==2*(b-t+1)+2*(r-l+1)-4: frames.append((c,t,b,l,r))
    singles=[(y,x,grid[y][x]) for y in range(h) for x in range(w) if grid[y][x] not in (0,5) and not any(grid[y][x]==c and t<=y<=b and l<=x<=r for c,t,b,l,r in frames)]
    for c,t,b,l,r in frames:
      if not singles: continue
      _,_,color=min(singles,key=lambda p:abs(p[0]-(t+b)//2)+abs(p[1]-(l+r)//2))
      for y in range(t+1,b):
       for x in range(l+1,r): out[y][x]=color if (y-t-1+x-l-1)%2==0 else 0
    for y in range(h):
     for x in range(w):
      if grid[y][x] and not any(grid[y][x]==c and t<=y<=b and l<=x<=r for c,t,b,l,r in frames): out[y][x]=0
    return out
